"use client";
import { useId } from "react";
import Link from "next/link";
import { ChevronRight, Download, Pencil } from "lucide-react";
import { DeleteButton } from "@/components/forms";
import { HighlightedText } from "./HighlightedText";
import styles from "./templates.module.css";

export type SavedTemplate = {
  id: string;
  name: string;
  subject: string;
  body: string;
};

export function TemplateListItem({
  template,
  open,
  onToggle,
  editHref,
}: {
  template: SavedTemplate;
  open: boolean;
  onToggle: () => void;
  editHref: string;
}) {
  const id = useId();
  return (
    <li
      className={`${styles.card} [background:var(--tpl-card)] [border:1px_solid_var(--tpl-line)] rounded-[22px] min-w-0 panel`}
    >
      <div className="flex items-center gap-3.5 py-4 px-4.5 [@media(max-width:_820px)]:flex-wrap">
        <button
          type="button"
          className={`${styles.chevron} w-11 h-11 rounded-[10px] [border:1px_solid_var(--tpl-line)] grid place-items-center flex-none text-[var(--tpl-muted)] cursor-pointer`}
          aria-label={`Preview ${template.name}`}
          aria-expanded={open}
          aria-controls={id}
          onClick={onToggle}
        >
          <ChevronRight
            size={18}
            aria-hidden="true"
            className={
              open ? `${styles.rotated} text-[var(--tpl-token)]` : undefined
            }
          />
        </button>
        <div className="flex-1 min-w-0">
          <button
            type="button"
            className="block text-[16px] font-bold tracking-[-0.01em] text-left cursor-pointer wrap-anywhere min-h-11"
            aria-expanded={open}
            aria-controls={id}
            onClick={onToggle}
          >
            {template.name}
          </button>
          <p
            className={
              open
                ? `text-[var(--tpl-muted)] text-[13.5px] whitespace-pre-wrap wrap-anywhere`
                : "text-[var(--tpl-muted)] text-[13.5px] whitespace-nowrap wrap-anywhere overflow-hidden text-ellipsis"
            }
          >
            <HighlightedText text={template.subject} />
          </p>
        </div>
        <div
          className="flex gap-1.5 items-center flex-wrap [@media(max-width:_820px)]:ml-14.5 [@media(max-width:_480px)]:ml-0 [@media(max-width:_480px)]:w-full"
          role="group"
          aria-label={`Actions for ${template.name}`}
        >
          <Link
            className="button-interaction ghost-button inline-flex items-center justify-center gap-2 py-2 px-[13px] min-h-11 rounded-[10px] text-[13.5px] font-semibold text-[var(--tpl-muted)] no-underline"
            href={editHref}
            aria-label={`Edit ${template.name}`}
          >
            <Pencil size={15} aria-hidden="true" />
            Edit
          </Link>
          <a
            className="button-interaction ghost-button inline-flex items-center justify-center gap-2 py-2 px-[13px] min-h-11 rounded-[10px] text-[13.5px] font-semibold text-[var(--tpl-muted)] no-underline"
            download
            href={`/api/templates/${template.id}/export`}
            aria-label={`Download JSON for ${template.name}`}
            title="Download JSON"
          >
            <Download size={16} aria-hidden="true" />
          </a>
          <DeleteButton id={template.id} kind="template" />
        </div>
      </div>
      <section
        id={id}
        hidden={!open}
        className={`${styles.preview} [margin:0_18px_18px_76px] py-4 px-4.5 rounded-[14px] [background:var(--tpl-inset)] [border:1px_solid_var(--tpl-line)] whitespace-pre-wrap wrap-anywhere text-[14.5px] leading-[1.7] max-h-110 overflow-y-auto [@media(max-width:_820px)]:ml-4.5`}
        aria-label={`Message preview: ${template.name}`}
        tabIndex={0}
      >
        <HighlightedText text={template.body} />
      </section>
    </li>
  );
}
